def slice_model(x: float) -> float:
    if x == int(x):  # real: x == int(x)
        xi: int = int(x)  # real: int(x)
        factorial_x_minus_1: int = 1
        i: int = 2
        while i <= xi - 1:
            factorial_x_minus_1 = factorial_x_minus_1 * i
            i = i + 1
        return float(factorial_x_minus_1)

def main():
    x = nondet_float()
    __ESBMC_assume(abs(x) <= 1000)  # Loose magnitude bound
    result = slice_model(x)
    assert (x == int(x)) == (result == float(int(x)))  # Check equivalence

